INSERT INTO products (id,name,category,price,sales,rating,image,description,review,gallery) VALUES
(1,'TAG Heuer','Watch',24900,'1,200','4.9 (124 reviews)','img/Watch/1/1.png','Crafted meticulously with solid gold plating, detailed chronograph metrics, and scratch-resistant sapphire glass on an alligator pattern strap.','"A classic timepiece that commands respect. Exceptionally premium gold sheen." - Vikram S.','["img/Watch/1/1.png"]'),
(2,'Rolex Submariner Green','Watch',12500,'850','4.7 (85 reviews)','img/Watch/2/2.png','Uncompromising matte-carbon structure featuring tactical rubber components, sleek date tracking, and military grade durability metrics.','"Brilliant styling! The stealth-black matte casing feels modern yet tactical." - Arjun K.','["img/Watch/2/2.png"]'),
(3,'Fossil Bowman','Watch',17900,'430','4.8 (64 reviews)','img/Watch/3/1.png','Engineered for deep-sea exploration, featuring glowing structural dials, professional unidirectional bezels, and 200m water resistance.','"Solid underwater utility coupled with high-end premium design." - Captain Raghav','["img/Watch/3/1.png"]'),
(4,'Rolex Sky-Dweller','Watch',9999,'2,100','4.6 (210 reviews)','img/Watch/4/1.png','Elegance structured in simplicity. Built using an ultra-lightweight stainless steel mesh band with a security magnetic locking mechanism.','"Perfect corporate accessory. Brilliantly thin casing and very comfortable." - Priya R.','["img/Watch/4/1.png"]'),
(6,'RayBan Reverse Black Green 0502','Goggles',14999,'3,000','4.9 (410 reviews)','img/Goggle/1/1.jpeg','An eternal shape constructed with 18k gold-plated frames and high-contrast polarization blocking 100% UV glare.','"The frame is impossibly light. Polarization makes outdoor environments super vivid." - Rohan J.','["img/Goggle/1/1.jpeg", "img/Goggle/1/2.jpeg", "img/Goggle/1/3.jpeg"]'),
(7,'Cartier Gold Blue Shaded 8070','Goggles',8999,'5,000','4.5 (180 reviews)','img/Goggle/2/1.jpeg','Hypoallergenic handcrafted acetate tortoise rims loaded with subtle gradient black transition lenses.','"Timeless and looks great with absolutely any outfit." - Kabir S.','["img/Goggle/2/1.jpeg", "img/Goggle/2/2.jpeg", "img/Goggle/2/3.jpeg"]'),
(8,'Cartier Silver Blue 1043','Goggles',7999,'1,100','4.7 (340 reviews)','img/Goggle/3/1.jpeg','Impact resistant wrap-around shield lenses loaded with anti-condensation capabilities and premium rubber grips.','"Perfect companion for cycling. Does not fog up even in high humidity." - Devendra P.','["img/Goggle/3/1.jpeg", "img/Goggle/3/2.jpeg", "img/Goggle/3/3.jpeg"]'),
(9,'RayBan Tiger Black 0502','Goggles',11999,'600','4.8 (95 reviews)','img/Goggle/4/1.jpeg','Fine geometric styling highlighting thin wireframe elements and warm amber-toned lenses.','"Retro vibe is incredibly elegant. Highly recommended for sunny brunches." - Tanya S.','["img/Goggle/4/1.jpeg", "img/Goggle/4/2.jpeg", "img/Goggle/4/3.jpeg"]'),
(11,'Creed Aventus for Men Eau De Parfum Spray 100ml','Perfume',21500,'900','5.0 (450 reviews)','img/Perfume/1/1.jpg','A warm comforting embrace constructed using pure sustainable agarwood, deep leather accords, and dark clove warmth.','"Incredibly long projection. Stays on the skin for over 12 hours easily." - Zayd A.','["img/Perfume/1/1.jpg", "img/Perfume/1/2.webp", "img/Perfume/1/3.webp"]'),
(12,'YSL* Saintt Laurentt Libre Eau De perfume (90ml)','Perfume',6999,'4,000','4.6 (520 reviews)','img/Perfume/2/1.webp','Sparkling dew morning elements combined with authentic damask rose petals, citrus hints, and soft cashmere wood.','"Perfect daytime signature. Clean, light, and wonderfully floral." - Meera G.','["img/Perfume/2/1.webp", "img/Perfume/2/2.webp", "img/Perfume/2/3.webp"]'),
(13,'Guccii Flora Gorgeous Gardeniiaa Women','Perfume',5999,'2,500','4.3 (280 reviews)','img/Perfume/3/1.webp','An energetic burst of fresh Sicilian bergamot, fresh organic mint, crushed sage, and dry Virginian cedarwood notes.','"Instantly refreshing. Uplifting bright citrus projection." - Tariq N.','["img/Perfume/3/1.webp", "img/Perfume/3/2.webp"]'),
(14,'Azzaroo The Most Wanted Unisex Perfume (100 ml)','Perfume',15999,'1,300','4.8 (980 reviews)','img/Perfume/4/1.webp','Highly seductive night-wear formulation highlighting dark roasted tonka beans, Royal amber resin, and rich sandalwood essence.','"Mysterious and intoxicating scent profile. Truly sophisticated." - Isha R.','["img/Perfume/4/1.webp", "img/Perfume/4/2.webp", "img/Perfume/4/3.webp"]')
